// Tópico: mackenzie/bueiro-inteligente/{id_bueiro}/sensor/volume
// Payload: volume de resíduos na caixa da boca de lobo, em litros
const idBueiro = msg.topic.split('/')[2];
const volume = parseFloat(msg.payload);

if (isNaN(volume)) {
    node.warn(`Valor inválido em ${msg.topic}: ${msg.payload}`);
    return null;
}

// Cadastro dos bueiros: localização e capacidade da caixa (litros).
// Capacidade = dimensões internas da caixa (SINAPI) x 1000.
//   bueiro01: caixa simples 1,00 x 0,60 x 1,20 m = 720 L
//   bueiro02: caixa dupla   2,20 x 0,60 x 1,20 m = 1584 L
// Para incluir um novo bueiro, basta acrescentar uma linha aqui.
const cadastroBueiros = {
    bueiro01: {
        endereco: 'Rua da Consolação, 930 - Consolação, São Paulo/SP',
        latitude: -23.5475, longitude: -46.6520, capacidade_l: 720
    },
    bueiro02: {
        endereco: 'Rua Maria Antônia, 294 - Vila Buarque, São Paulo/SP',
        latitude: -23.5452, longitude: -46.6508, capacidade_l: 1584
    }
};

const local = cadastroBueiros[idBueiro];
if (!local) {
    node.warn(`Bueiro ${idBueiro} não cadastrado.`);
    return null;
}

// Regra 1 - classificação pela ocupação da caixa (%)
const LIMITE_ATENCAO = 50;
const LIMITE_CRITICO = 75;
const ocupacao = Math.round(volume / local.capacidade_l * 1000) / 10;

let status;
if (ocupacao >= LIMITE_CRITICO) status = 'vermelho';
else if (ocupacao >= LIMITE_ATENCAO) status = 'amarelo';
else status = 'verde';

// Guarda a última leitura de cada bueiro (usada na verificação da limpeza)
const ultimas = flow.get('ultimas') || {};
ultimas[idBueiro] = { volume_l: volume, ocupacao_pct: ocupacao, status: status };
flow.set('ultimas', ultimas);

msg.topic = idBueiro;          // separa o filtro "só quando muda" por bueiro
msg.id_bueiro = idBueiro;
msg.volume_l = volume;
msg.ocupacao_pct = ocupacao;
msg.status = status;
msg.local = local;

const cores = { verde: 'green', amarelo: 'yellow', vermelho: 'red' };
node.status({ fill: cores[status], shape: 'dot', text: `${idBueiro}: ${volume} L (${ocupacao}%)` });
return msg;

// Monta o ponto do InfluxDB: [campos, tags]
msg.payload = [
    {
        volume_l: msg.volume_l,
        capacidade_l: msg.local.capacidade_l,
        ocupacao_pct: msg.ocupacao_pct,
        status: msg.status,
        endereco: msg.local.endereco,
        latitude: msg.local.latitude,
        longitude: msg.local.longitude
    },
    { id_bueiro: msg.id_bueiro }
];
return msg;

// Regra 3 - limpeza automática: publica o comando para o bueiro crítico
msg.topic = `mackenzie/bueiro-inteligente/${msg.id_bueiro}/grade/comando`;
msg.payload = 'limpar';
node.status({ fill: 'blue', shape: 'dot', text: `limpeza solicitada: ${msg.id_bueiro}` });
return msg;

// Regra 4 - 15 s após o fim da limpeza, confere a ocupação atual do bueiro
// Saída 1: não resolveu (alerta à equipe)
// Saída 2: resolveu (apenas registro)
// Saída 3: registro do resultado no InfluxDB (measurement "limpezas")
const LIMITE_CRITICO = 75;

const idBueiro = msg.topic.split('/')[2];
const ultimas = flow.get('ultimas') || {};
const atual = ultimas[idBueiro];

if (!atual) {
    node.warn(`Sem leitura recente do ${idBueiro} para verificar a limpeza.`);
    return null;
}

const resolvida = atual.ocupacao_pct < LIMITE_CRITICO;

msg.id_bueiro = idBueiro;
msg.volume_l = atual.volume_l;
msg.ocupacao_pct = atual.ocupacao_pct;

const registro = {
    payload: [
        {
            resultado: resolvida ? 'resolvida' : 'nao_resolvida',
            volume_l: atual.volume_l,
            ocupacao_pct: atual.ocupacao_pct
        },
        { id_bueiro: idBueiro }
    ]
};

if (resolvida) {
    node.status({ fill: 'green', shape: 'dot', text: `${idBueiro}: resolvida (${atual.ocupacao_pct}%)` });
    msg.payload = `${idBueiro}: limpeza automática resolveu (ocupação ${atual.ocupacao_pct}%)`;
    return [null, msg, registro];
}
node.status({ fill: 'red', shape: 'dot', text: `${idBueiro}: não resolveu (${atual.ocupacao_pct}%)` });
return [msg, null, registro];

const token = env.get('TELEGRAM_BOT_TOKEN');
const chatId = env.get('TELEGRAM_CHAT_ID');

if (!token || !chatId) {
    node.warn('Configure TELEGRAM_BOT_TOKEN e TELEGRAM_CHAT_ID nas variáveis de ambiente da aba.');
    return null;
}

// Mesmo cadastro da function "Processar leitura"
const cadastroBueiros = {
    bueiro01: { endereco: 'Rua da Consolação, 930 - Consolação, São Paulo/SP', capacidade_l: 720 },
    bueiro02: { endereco: 'Rua Maria Antônia, 294 - Vila Buarque, São Paulo/SP', capacidade_l: 1584 }
};

const LIMITE_CRITICO = 75;
const LINK_DASHBOARD = env.get('LINK_DASHBOARD') || 'https://vibrantminivan1185.grafana.net';

const local = cadastroBueiros[msg.id_bueiro] || { endereco: 'Endereço não cadastrado', capacidade_l: 0 };

const fmt = (n, casas) => Number(n).toLocaleString('pt-BR', { minimumFractionDigits: casas, maximumFractionDigits: casas });

const dataHora = new Date().toLocaleString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
});

const texto =
    `🚨 <b>Limpeza manual necessária – ${msg.id_bueiro}</b>\n` +
    `📍 ${local.endereco}\n` +
    `\n` +
    `<b>Resíduos na caixa:</b> ${fmt(msg.volume_l, 0)} L de ${fmt(local.capacidade_l, 0)} L ` +
    `(${fmt(msg.ocupacao_pct, 1)}%, limite crítico: ${LIMITE_CRITICO}%)\n` +
    `A grade autolimpante foi acionada, mas não removeu os resíduos. ` +
    `Provável acúmulo de material grande (sacos, galhos ou entulho).\n` +
    `\n` +
    `👷 <b>O que fazer:</b> enviar a equipe de zeladoria para limpeza manual, evitando o entupimento do bueiro e o alagamento da via.\n` +
    `\n` +
    `🕘 ${dataHora} · 📊 <a href="${LINK_DASHBOARD}">Ver no dashboard</a>`;

msg.url = `https://api.telegram.org/bot${token}/sendMessage`;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    chat_id: chatId,
    text: texto,
    parse_mode: 'HTML',
    disable_web_page_preview: true
};
return msg;
